const cities=[{id:'nyc',name:'New York City',state:'New York',lat:40.73,lng:-73.97,dx:.027,dy:.021,base:34,canopy:22,impervious:67,zoom:11,icon:'▥'},{id:'philly',name:'Philadelphia',state:'Pennsylvania',lat:40.00,lng:-75.14,dx:.021,dy:.017,base:33,canopy:28,impervious:59,zoom:11,icon:'▤'},{id:'la',name:'Los Angeles',state:'California',lat:34.05,lng:-118.28,dx:.036,dy:.025,base:37,canopy:17,impervious:72,zoom:10,icon:'☀'}];
let current=cities[0],selected=null,map,overlay,layer='predicted';
function sample(c){const cells=[];for(let y=-5;y<=5;y++)for(let x=-5;x<=5;x++){if(x*x+y*y>31)continue;const n=(Math.sin((x+9)*12.9898+(y+8)*78.233+c.lat)*43758.5453)%1;const z=Math.abs(n);const green=Math.max(3,Math.min(65,c.canopy+(z-.5)*42));const impervious=Math.max(12,Math.min(91,c.impervious-(green-c.canopy)*.7));const predicted=c.base+(impervious-c.impervious)*.08-(green-c.canopy)*.09+Math.sin(x*.8+y)*1.2;const error=(z-.5)*3;cells.push({id:`${c.id.toUpperCase()}-${cells.length+1}`,lat:c.lat+y*c.dy,lng:c.lng+x*c.dx,green,impervious,predicted,observed:predicted-error,error});}return cells;}
cities.forEach(c=>c.cells=sample(c));
function mean(c,key){return c.cells.reduce((s,d)=>s+d[key],0)/c.cells.length;}
function color(d){const v=layer==='green'?d.green/65:layer==='error'?(d.error+2)/4:(d[layer]-24)/20;const palette=layer==='green'?['#e9eac9','#bccb91','#7ca063','#3b6b49']:layer==='error'?['#517d96','#c7d9dc','#ede4cf','#bb704f']:['#ece6b1','#e9ba6b','#d67d48','#ac4436'];return palette[Math.min(3,Math.max(0,Math.floor(v*4)))];}
function detail(d){selected=d;document.getElementById('detail').innerHTML=`<h3>${d.id}</h3><p class="small">Synthetic analysis cell · demo values</p><div class="detail-values"><div><small>AI-predicted</small><b>${d.predicted.toFixed(1)}°C</b></div><div><small>Observed</small><b>${d.observed.toFixed(1)}°C</b></div><div><small>Tree canopy</small><b>${d.green.toFixed(0)}%</b></div><div><small>Impervious</small><b>${d.impervious.toFixed(0)}%</b></div></div><p class="small">Residual (prediction − observation): ${d.error.toFixed(1)}°C</p>`;}
function draw(){if(!map)return;if(overlay)overlay.remove();overlay=L.layerGroup().addTo(map);current.cells.forEach(d=>{const bounds=[[d.lat-current.dy*.47,d.lng-current.dx*.47],[d.lat+current.dy*.47,d.lng+current.dx*.47]];L.rectangle(bounds,{color:'#fff',weight:.6,fillColor:color(d),fillOpacity:Number(document.getElementById('opacity').value)/100}).addTo(overlay).on('click',()=>detail(d));});}
function selectCity(id){current=cities.find(c=>c.id===id);document.querySelectorAll('.city').forEach(b=>{b.classList.toggle('active',b.dataset.city===id);b.setAttribute('aria-pressed',b.dataset.city===id);});document.getElementById('mapTitle').textContent=current.name;document.getElementById('metrics').innerHTML=[['Mean predicted surface temperature',mean(current,'predicted').toFixed(1)+'°C','Synthetic summer sample'],['Mean tree canopy',mean(current,'green').toFixed(0)+'%','Illustrative land cover'],['Mean impervious cover',mean(current,'impervious').toFixed(0)+'%','Illustrative land cover'],['Analysis cells',current.cells.length,'Schematic grid · not city boundary']].map(d=>`<article class="metric"><span>${d[0]}</span><strong>${d[1]}</strong><small>${d[2]}</small></article>`).join('');if(map)map.setView([current.lat,current.lng],current.zoom);draw();detail(current.cells[Math.floor(current.cells.length/2)]);}
document.getElementById('cities').innerHTML=cities.map(c=>`<button class="city" data-city="${c.id}"><span class="city-icon">${c.icon}</span><span><strong>${c.name}</strong><small>${c.state}</small></span><span class="arrow">↗</span></button>`).join('');document.querySelectorAll('.city').forEach(b=>b.onclick=()=>selectCity(b.dataset.city));
if(window.L){map=L.map('map',{scrollWheelZoom:true}).setView([current.lat,current.lng],11);L.tileLayer('https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png',{attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> &copy; <a href="https://carto.com/attributions">CARTO</a>',maxZoom:19}).addTo(map);}else document.getElementById('mapFallback').hidden=false;
document.getElementById('layer').onchange=e=>{layer=e.target.value;const green=layer==='green',error=layer==='error';document.getElementById('legendLabel').textContent=green?'Tree canopy · %':error?'Prediction − observation · °C':'Surface temperature · °C';document.getElementById('legendLow').textContent=green?'0%':error?'−2°':'24°';document.getElementById('legendHigh').textContent=green?'65%':error?'+2°':'44°';document.getElementById('gradient').style.background=green?'linear-gradient(90deg,#e9eac9,#3b6b49)':error?'linear-gradient(90deg,#517d96,#ede4cf,#bb704f)':'linear-gradient(90deg,#ece6b1,#e9ba6b,#d67d48,#ac4436)';draw();};
document.getElementById('opacity').oninput=e=>{document.getElementById('opacityValue').textContent=e.target.value+'%';draw();};
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{document.querySelectorAll('nav button').forEach(n=>n.classList.toggle('active',n===b));document.querySelectorAll('.view').forEach(v=>v.hidden=v.id!==b.dataset.view);if(b.dataset.view==='explore'&&map)setTimeout(()=>map.invalidateSize(),50);});
document.getElementById('comparison').innerHTML=cities.map(c=>`<article class="paper compare-card"><div class="eyebrow">${c.state.toUpperCase()} · DEMO</div><h2>${c.name}</h2><span class="big">${mean(c,'predicted').toFixed(1)}°C</span><p>Mean synthetic predicted surface temperature</p>${[['Tree canopy','green'],['Impervious cover','impervious']].map(([name,key])=>`<div class="bar-row"><div><span>${name}</span><b>${mean(c,key).toFixed(0)}%</b></div><div class="bar"><i style="width:${mean(c,key)}%"></i></div></div>`).join('')}<p class="small">${c.cells.length} schematic cells · sample values only</p></article>`).join('');
document.getElementById('download').onclick=()=>{const rows=['data_status,city,cell_id,latitude,longitude,predicted_surface_c,observed_surface_c,residual_c,tree_canopy_pct,impervious_pct',...current.cells.map(d=>['SYNTHETIC_DEMO',current.name,d.id,d.lat,d.lng,d.predicted.toFixed(2),d.observed.toFixed(2),d.error.toFixed(2),d.green.toFixed(2),d.impervious.toFixed(2)].join(','))];const u=URL.createObjectURL(new Blob([rows.join('\n')],{type:'text/csv'}));const a=document.createElement('a');a.href=u;a.download=`heatscape-${current.id}-SYNTHETIC-DEMO.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};selectCity('nyc');
